CREATE POLICY "Applicants upload resumes" ON storage.objects FOR INSERT TO anon,authenticated WITH CHECK(bucket_id='resumes' AND lower(storage.extension(name)) IN ('pdf','doc','docx')); CREATE POLICY "Admins read resumes" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='resumes' AND public.has_role(auth.uid(),'admin')); CREATE POLICY "Admins delete resumes" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='resumes' AND public.has_role(auth.uid(),'admin'));